" 49 :   public void visit(NodeTraversal t, Node n, Node parent) {
 50 :     // VOID nodes appear when there are extra semicolons at the BLOCK level.
 51 :     // I've been unable to think of any cases where this indicates a bug,
 52 :     // and apparently some people like keeping these semicolons around,
 53 :     // so we'll allow it.
 54 :     if (n.getType() == Token.EMPTY ||
 55 :         n.getType() == Token.COMMA) {
 56 :       return;
 57 :     }
 58 : 
 59 :     if (parent == null)
 60 :       return;
 61 : 
 62 :     int pt = parent.getType();
 63 :     if (pt == Token.COMMA) {
 64 :       if (n == parent.getLastChild()) {
 65 :         for (Node an : parent.getAncestors()) {
 66 :           int ancestorType = an.getType();
 67 :           if (ancestorType == Token.COMMA)
 68 :             continue;
 69 :           if (ancestorType != Token.EXPR_RESULT &&
 70 :               ancestorType != Token.BLOCK)
 71 :             return;
 72 :           else
 73 :             break;
 74 :         }
 75 :       }
 76 :     } else if (pt != Token.EXPR_RESULT && pt != Token.BLOCK) {
 77 :       if (pt == Token.FOR && parent.getChildCount() == 4 &&
 78 :           (n == parent.getFirstChild() ||
 79 :            n == parent.getFirstChild().getNext().getNext())) {
 80 :         // Fall through and look for warnings for the 1st and 3rd child
 81 :         // of a for.
 82 :       } else {
 83 :         return;  // it might be ok to not have a side-effect
 84 :       }
 85 :     }
 86 :     if (NodeUtil.isSimpleOperatorType(n.getType()) ||
 87 :         !NodeUtil.mayHaveSideEffects(n)) {
 88 :       if (n.isQualifiedName() && n.getJSDocInfo() != null) {
 89 :         // This no-op statement was there so that JSDoc information could
 90 :         // be attached to the name. This check should not complain about it.
 91 :         return;
 92 :       } else if (NodeUtil.isExpressionNode(n)) {
 93 :         // we already reported the problem when we visited the child.
 94 :         return;
 95 :       }
 96 : 
 97 :       String msg = "This code lacks side-effects. Is there a bug?";
 98 :       if (n.getType() == Token.STRING) {
 99 :         msg = "Is there a missing '+' on the previous line?";
100 :       }
101 : 
102 :       t.getCompiler().report(
103 :           JSError.make(t, n, level, USELESS_CODE_ERROR, msg));
104 :     }
105 :   }"

"569 :   private void updateObjLitOrFunctionDeclarationAtAssignNode(
570 :       Name n, String alias) {
571 :     // NOTE: It's important that we don't add additional nodes
572 :     // (e.g. a var node before the exprstmt) because the exprstmt might be
573 :     // the child of an if statement that's not inside a block).
574 : 
575 :     Ref ref = n.declaration;
576 :     Node rvalue = ref.node.getNext();
577 :     Node varNode = new Node(Token.VAR);
578 :     Node varParent = ref.node.getAncestor(3);
579 :     Node gramps = ref.node.getAncestor(2);
580 :     boolean isObjLit = rvalue.getType() == Token.OBJECTLIT;
581 : 
582 :     if (isObjLit && n.canEliminate()) {
583 :       // Eliminate the object literal altogether.
584 :       varParent.replaceChild(gramps, varNode);
585 :       ref.node = null;
586 : 
587 :     } else {
588 :       if (rvalue.getType() == Token.FUNCTION) {
589 :         checkForHosedThisReferences(rvalue, n.docInfo, n);
590 :       }
591 : 
592 :       ref.node.getParent().removeChild(rvalue);
593 : 
594 :       Node nameNode = NodeUtil.newName(
595 :           alias, ref.node.getAncestor(2), n.fullName());
596 : 
597 :       if (ref.node.getLastChild().getBooleanProp(Node.IS_CONSTANT_NAME)) {
598 :         nameNode.putBooleanProp(Node.IS_CONSTANT_NAME, true);
599 :       }
600 : 
601 :       varNode.addChildToBack(nameNode);
602 :       nameNode.addChildToFront(rvalue);
603 :       varParent.replaceChild(gramps, varNode);
604 : 
605 :       // Update the node ancestry stored in the reference.
606 :       ref.node = nameNode;
607 :     }
608 : 
609 :     if (isObjLit) {
610 :       boolean discardKeys = n.aliasingGets == 0;
611 :       declareVarsForObjLitValues(
612 :           alias, rvalue,
613 :           varNode, varParent.getChildBefore(varNode), varParent,
614 :           discardKeys);
615 :     }
616 : 
617 :     addStubsForUndeclaredProperties(n, alias, varParent, varNode);
618 : 
619 :     if (!varNode.hasChildren()) {
620 :       varParent.removeChild(varNode);
621 :     }
622 : 
623 :     compiler.reportCodeChange();
624 :   }"

"811 :   private int addStubsForUndeclaredProperties(
812 :       Name n, String alias, Node parent, Node addAfter) {
813 :     Preconditions.checkArgument(NodeUtil.isStatementBlock(parent));
814 :     int numStubs = 0;
815 :     if (n.props != null) {
816 :       for (Name p : n.props) {
817 :         if (p.needsToBeStubbed()) {
818 :           String propAlias = alias + '$' + p.name;
819 :           Node nameNode = Node.newString(Token.NAME, propAlias);
820 :           Node newVar = new Node(Token.VAR, nameNode);
821 :           if (addAfter == null) {
822 :             parent.addChildToFront(newVar);
823 :           } else {
824 :             parent.addChildAfter(newVar, addAfter);
825 :             addAfter = newVar;
826 :           }
827 :           numStubs++;
828 :           compiler.reportCodeChange();
829 : 
830 :           // Determine if this is a constant var by checking the first
831 :           // reference to it. Don't check the declaration, as it might be null.
832 :           if (p.refs.get(0).node.getLastChild().getBooleanProp(
833 :                 Node.IS_CONSTANT_NAME)) {
834 :             nameNode.putBooleanProp(Node.IS_CONSTANT_NAME, true);
835 :           }
836 :         }
837 :       }
838 :     }
839 :     return numStubs;
840 :   }"

"547 :   private void updateObjLitOrFunctionDeclaration(Name n, String alias) {
548 :     switch (n.declaration.node.getParent().getType()) {
549 :       case Token.ASSIGN:
550 :         updateObjLitOrFunctionDeclarationAtAssignNode(n, alias);
551 :         break;
552 :       case Token.VAR:
553 :         updateObjLitOrFunctionDeclarationAtVarNode(n);
554 :         break;
555 :       case Token.FUNCTION:
556 :         updateFunctionDeclarationAtFunctionNode(n);
557 :         break;
558 :     }
