"414 :   private void flattenNameRef(String alias, Node n, Node parent,
415 :       String originalName) {
416 :     // BEFORE:
417 :     //   getprop
418 :     //     getprop
419 :     //       name a
420 :     //       string b
421 :     //     string c
422 :     // AFTER:
423 :     //   name a$b$c
424 :     Node ref = NodeUtil.newName(alias, n, originalName);
425 :     if (n.getLastChild().getBooleanProp(Node.IS_CONSTANT_NAME)) {
426 :       ref.putBooleanProp(Node.IS_CONSTANT_NAME, true);
427 :     }
428 :     parent.replaceChild(n, ref);
